CREATE TABLE IF NOT EXISTS mig18_customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT NOT NULL, segment TEXT);
INSERT INTO mig18_customers(customer_id, customer_name) VALUES (1, 'Asha'), (2, 'Bilal'), (3, 'Mira');
UPDATE mig18_customers SET segment = 'standard' WHERE segment IS NULL AND customer_id BETWEEN 1 AND 2;
UPDATE mig18_customers SET segment = 'standard' WHERE segment IS NULL;
SELECT COUNT(*) AS missing_segments FROM mig18_customers WHERE segment IS NULL;

